package dustin.cex.domains.kyc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.domains.mail.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionTemplate;

/** 실제 DB·SMTP/TLS·불변 발송함·임대 회복과 외부 결과의 불확실성을 검증한다. */
class CustomerMailOutboxIntegrationTest extends CustomerMailTestSupport {
    @Test void encryptedQueueDoesNotExposeAddressOrToken(){String secret=token();var id=queue(UUID.randomUUID(),secret,Instant.now().plusSeconds(600));var row=jdbc.queryForMap("SELECT * FROM customer_mail_jobs WHERE id=?",id);assertFalse(row.toString().contains(secret));assertFalse(row.toString().contains(customer.getEmail()));assertEquals(secret,outbox.open(id).token());assertFalse(outbox.open(id).toString().contains(secret));}
    @Test void producerRollbackLeavesNoDeliverableJob(){UUID reference=UUID.randomUUID();assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(t->{outbox.enqueue(customer.getId(),CustomerMailOutbox.Kind.EMAIL_VERIFICATION,reference,customer.getEmail(),token(),Instant.now().plusSeconds(600));throw new IllegalStateException("격리 업무 실패");}));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE reference_id=?",Long.class,reference));}
    @Test void duplicateBusinessReferenceReplaysButChangedPayloadFails(){UUID reference=UUID.randomUUID();String secret=token();Instant expires=Instant.now().plusSeconds(600).truncatedTo(java.time.temporal.ChronoUnit.MICROS);var id=queue(reference,secret,expires);assertEquals(id,queue(reference,secret,expires));assertThrows(IllegalStateException.class,()->queue(reference,token(),expires));}
    @org.springframework.beans.factory.annotation.Autowired org.springframework.mail.javamail.JavaMailSender sender;
    @org.springframework.beans.factory.annotation.Autowired dustin.cex.domains.cdd.CddCrypto mailCrypto;
    @Test void actualSmtpsAcceptsFixedTemplateAndStableMessageId() throws Exception {smtp.requireReady();((org.springframework.mail.javamail.JavaMailSenderImpl)sender).testConnection();UUID id=queued();assertTrue(dispatcher.dispatchOnce());assertEquals("SMTP_ACCEPTED",outbox.state(id).status());assertTrue(server().waitForIncomingEmail(3000,1));var message=server().getReceivedMessages()[0];assertEquals("<"+id+"@exchange.test>",message.getMessageID());assertEquals(customer.getEmail(),message.getAllRecipients()[0].toString());String body=(String)message.getContent();assertTrue(body.contains("https://exchange.example.test/account/verify-email?challenge="));assertTrue(body.contains(outbox.open(id).token()));}
    @Test void accountDisableSuppressesBeforeAnySmtp(){UUID id=queued();var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);dispatcher.dispatchOnce();assertEquals("SUPPRESSED",outbox.state(id).status());assertEquals(0,server().getReceivedMessages().length);}
    @Test void changedRecipientSuppressesBeforeAnySmtp(){UUID id=queued();var u=users.findById(customer.getId()).orElseThrow();u.setEmail(UUID.randomUUID()+"@other.invalid");users.saveAndFlush(u);dispatcher.dispatchOnce();assertEquals("SUPPRESSED",outbox.state(id).status());assertEquals(0,server().getReceivedMessages().length);}
    @Test void concurrentClaimHasOneOwner() throws Exception {UUID id=queued();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();return outbox.claim();});var b=pool.submit(()->{start.await();return outbox.claim();});start.countDown();var first=a.get(10,TimeUnit.SECONDS);var second=b.get(10,TimeUnit.SECONDS);assertEquals(1,(first==null?0:1)+(second==null?0:1));assertEquals(id,(first==null?second:first).id());}finally{pool.shutdownNow();}}
    @Test void expiredLeaseCanBeReclaimedButOldOwnerCannotOverwrite(){UUID id=queued();var old=outbox.claim();jdbc.update("UPDATE customer_mail_delivery SET lease_until=clock_timestamp()-interval '1 second' WHERE job_id=?",id);var current=outbox.claim();assertNotEquals(old.token(),current.token());assertFalse(outbox.finish(old,"SMTP_ACCEPTED"));assertEquals("SENDING",outbox.state(id).status());assertTrue(outbox.finish(current,"SUPPRESSED"));}
    @Test void smtpResultAuditFailureRollsBackAndSameLeaseCanRetry(){UUID id=queued();var lease=outbox.claim();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(isNull(),eq("CUSTOMER_MAIL_RESULT"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->outbox.finish(lease,"SMTP_ACCEPTED"));reset(audit);assertEquals("SENDING",outbox.state(id).status());assertTrue(outbox.finish(lease,"SMTP_ACCEPTED"));}
    @Test void retryStopsAtFiveClaimsWithoutFalseSuccess(){UUID id=queued();for(int i=0;i<5;i++){var lease=outbox.claim();assertNotNull(lease);outbox.finish(lease,"SMTP_UNKNOWN");jdbc.update("UPDATE customer_mail_delivery SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_id=?",id);}assertEquals("EXHAUSTED",outbox.state(id).status());assertEquals(5,outbox.state(id).attempts());assertNull(outbox.claim());}
    @Test void immutableJobsAndAttemptsRejectUpdateDeleteTruncate(){queued();outbox.claim();for(String table:List.of("customer_mail_jobs","customer_mail_attempts"))for(String sql:List.of("UPDATE "+table+" SET id=id","DELETE FROM "+table,"TRUNCATE "+table+" CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));}
    @Test void expiredClaimAfterActualSmtpCanDuplicateSameMessageId() throws Exception {UUID id=queued();var lease=outbox.claim();smtp.send(outbox.open(id));jdbc.update("UPDATE customer_mail_delivery SET lease_until=clock_timestamp()-interval '1 second' WHERE job_id=?",id);dispatcher.dispatchOnce();assertTrue(server().waitForIncomingEmail(3000,2));var messages=server().getReceivedMessages();assertEquals(messages[0].getMessageID(),messages[1].getMessageID());assertEquals("SMTP_ACCEPTED",outbox.state(id).status());assertFalse(outbox.finish(lease,"SMTP_ACCEPTED"));}
    UUID oldPayload(Instant expiry,String status){
        UUID id=UUID.randomUUID();var p=new CustomerMailOutbox.Payload("CUSTOMER_MAIL_V1",id,customer.getId(),CustomerMailOutbox.Kind.EMAIL_VERIFICATION,UUID.randomUUID(),customer.getEmail(),token(),expiry);String raw=json.writeValueAsString(p);
        jdbc.update("INSERT INTO customer_mail_jobs(id,user_id,kind,reference_id,content_mac,key_id,expires_at) VALUES(?,?,?,?,?,?,?)",id,customer.getId(),p.kind().name(),p.reference(),mailCrypto.fingerprint("customer-mail-envelope-v1",raw),mailCrypto.keyId(),java.sql.Timestamp.from(expiry));
        jdbc.update("INSERT INTO customer_mail_payloads(job_id,payload_cipher) VALUES(?,?)",id,mailCrypto.encrypt(customer.getId(),id,raw.getBytes(java.nio.charset.StandardCharsets.UTF_8)));jdbc.update("INSERT INTO customer_mail_delivery(job_id,status) VALUES(?,?)",id,status);return id;
    }
    @Test void activeOrRecentPayloadCannotBePurged(){UUID active=queued();UUID recent=oldPayload(Instant.now().minusSeconds(60).truncatedTo(java.time.temporal.ChronoUnit.MICROS),"SUPPRESSED");for(var id:List.of(active,recent))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("DELETE FROM customer_mail_payloads WHERE job_id=?",id));assertEquals(0,outbox.pruneExpiredPayloads());}
    @Test void terminalExpiredPayloadCanBePurgedWithoutDeletingAuditOrJob(){UUID id=oldPayload(Instant.now().minusSeconds(172800).truncatedTo(java.time.temporal.ChronoUnit.MICROS),"SMTP_ACCEPTED");assertEquals(1,outbox.pruneExpiredPayloads());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE id=?",Long.class,id));assertEquals("SMTP_ACCEPTED",outbox.state(id).status());assertThrows(org.springframework.dao.DataAccessException.class,()->outbox.open(id));}
    @Test void purgeAuditFailureRestoresCiphertext(){UUID id=oldPayload(Instant.now().minusSeconds(172800).truncatedTo(java.time.temporal.ChronoUnit.MICROS),"EXHAUSTED");doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(isNull(),eq("CUSTOMER_MAIL_PAYLOADS_PRUNED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->outbox.pruneExpiredPayloads());reset(audit);assertNotNull(outbox.open(id));assertEquals(1,outbox.pruneExpiredPayloads());}
    @Test void expiredQueuedPayloadIsSuppressedWithoutSmtp(){UUID id=oldPayload(Instant.now().minusSeconds(60).truncatedTo(java.time.temporal.ChronoUnit.MICROS),"PENDING");dispatcher.dispatchOnce();assertEquals("SUPPRESSED",outbox.state(id).status());assertEquals(0,server().getReceivedMessages().length);}

}
